const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET || $env.N8N_SHARED_SECRET;
if (!secret) { throw new Error('LENDLOOP_HMAC_SECRET manquant'); }

const headers = $input.first().json.headers || {};
const ts = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
const sig = (headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'] || '').toLowerCase();
const body = typeof $input.first().json.body === 'string'
  ? $input.first().json.body
  : JSON.stringify($input.first().json.body ?? $input.first().json);

if (!ts || !sig) { throw new Error('Headers HMAC manquants'); }
const skew = Math.abs(Date.now() - Number(ts));
if (skew > 5 * 60 * 1000) { throw new Error('Timestamp hors fenêtre'); }

const expected = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
if (expected !== sig) { throw new Error('Signature invalide'); }

const payload = typeof $input.first().json.body === 'object'
  ? $input.first().json.body
  : JSON.parse(body);

return [{ json: { ok: true, verified: true, payload, receivedAt: new Date().toISOString() } }];

